head.script:
scwin.onpageload = function () {
    // 버튼 초기화
    btn_save.show("");
    btn_edit.hide();
    btn_delete.hide();

    // 페이지 정보 초기화
    scwin.initPaginationInfo();

    // 전체 데이터 조회를 위해 페이지 크기를 크게 설정
    dmp_issVo.set("pageIndex", "1");
    dmp_issVo.set("pageSize", "1000");

    // search_box
    var cptIbxName = $p.getComponentById("searchComp_1");
    if (cptIbxName == undefined) {
        search_box.hide();
    }

    // 이슈리스크관리 조회
    scwin.btn_search_onclick();
};

// 각 그리드별 페이지 정보 초기화
scwin.initPaginationInfo = function () {
    console.log("페이지 정보 초기화 시작");

    // 전체 데이터 페이지 정보
    scwin.allDataPageInfo = {
        currentPage: 1,
        pageSize: 10,
        totalCount: 0,
        data: []
    };

    // 대기 데이터 페이지 정보
    scwin.waitingPageInfo = {
        currentPage: 1,
        pageSize: 10,
        totalCount: 0,
        data: []
    };

    // 진행중 데이터 페이지 정보
    scwin.processingPageInfo = {
        currentPage: 1,
        pageSize: 10,
        totalCount: 0,
        data: []
    };

    // 완료 데이터 페이지 정보
    scwin.completedPageInfo = {
        currentPage: 1,
        pageSize: 10,
        totalCount: 0,
        data: []
    };
};

// 페이지별 데이터 분할 함수
scwin.getPageData = function (data, pageInfo) {
    if (!data || !pageInfo) {
        console.error("getPageData: 데이터 또는 페이지 정보가 없습니다.");
        return [];
    }

    var startIndex = (pageInfo.currentPage - 1) * pageInfo.pageSize;
    var endIndex = startIndex + pageInfo.pageSize;
    return data.slice(startIndex, endIndex);
};

// 페이지 네비게이터 업데이트 함수
scwin.updatePagination = function (pageInfo, paginationComponent) {
    if (!pageInfo || !paginationComponent) {
        console.error("updatePagination: 페이지 정보 또는 컴포넌트가 없습니다.");
        return;
    }

    var totalPages = Math.ceil(pageInfo.totalCount / pageInfo.pageSize);
    if (totalPages > 0) {
        paginationComponent.setCount(totalPages);
        paginationComponent.setSelectedIndex(pageInfo.currentPage);
    }
};

/************************** 조회 관련 함수 *************************/

// 조회 버튼 클릭 이벤트
scwin.btn_search_onclick = function (e) {
    if (!scwin.allDataPageInfo) {
        scwin.initPaginationInfo();
    }

    dmp_issVo.set("pageIndex", "1");
    dmp_issVo.set("pageSize", "1000");
    scwin.allDataPageInfo.currentPage = 1;

    $c.sbm.execute($p, sbm_selectIssVoList);
};

// 서버 조회 결과 처리
scwin.sbm_issList_submitdone = function (e) {
    console.log("서버 응답 수신", e);


    if (!scwin.allDataPageInfo) {
        scwin.initPaginationInfo();
    }

    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    // 전체 데이터 저장
    var allData = elData.issVoList || [];
    console.log("전체 데이터:", allData.length, "개");

    scwin.allDataPageInfo.data = allData;
    scwin.allDataPageInfo.totalCount = elData.totalCount;

    // status별로 데이터 필터링
    var waitingData = [];
    var processingData = [];
    var completedData = [];

    for (var i = 0; i < allData.length; i++) {
        var item = allData[i];
        if (item.status === "PEN") {
            waitingData.push(item);
        } else if (item.status === "IPR") {
            processingData.push(item);
        } else if (item.status === "COM") {
            completedData.push(item);
        }
    }

    // 각 그리드별 데이터 저장
    scwin.waitingPageInfo.data = waitingData;
    scwin.waitingPageInfo.totalCount = waitingData.length;
    scwin.waitingPageInfo.currentPage = 1;

    scwin.processingPageInfo.data = processingData;
    scwin.processingPageInfo.totalCount = processingData.length;
    scwin.processingPageInfo.currentPage = 1;

    scwin.completedPageInfo.data = completedData;
    scwin.completedPageInfo.totalCount = completedData.length;
    scwin.completedPageInfo.currentPage = 1;

    // 그리드 업데이트
    scwin.updateGridData();

    // 페이지 네비게이터 업데이트
    var serverPageInfo = {
        currentPage: 1,
        pageSize: 10,
        totalCount: elData.totalCount
    };
    scwin.updatePagination(serverPageInfo, pgl_issList);
    scwin.updatePagination(scwin.waitingPageInfo, pgl_waiting);
    scwin.updatePagination(scwin.processingPageInfo, pgl_processing);
    scwin.updatePagination(scwin.completedPageInfo, pgl_com);

    // 카운트 업데이트
    spn_waitListCnt.setLabel(waitingData.length);
    spn_processingListCnt.setLabel(processingData.length);
    spn_completeListCnt.setLabel(completedData.length);
    spn_listCnt.setLabel(elData.totalCount);

    // 폼 초기화
    dmp_issVoDetail.setEmptyValue();
};

// 각 그리드 데이터 업데이트
scwin.updateGridData = function () {
    console.log("그리드 데이터 업데이트 시작");

    try {
        // 전체 데이터 그리드
        if (scwin.allDataPageInfo && scwin.allDataPageInfo.data) {
            var displayPageSize = 10;
            var currentPage = 1;
            var startIndex = 0;
            var endIndex = displayPageSize;

            var allPageData = scwin.allDataPageInfo.data.slice(startIndex, endIndex);
            dlt_issVoList.setJSON(allPageData);
        }

        // 대기 그리드
        if (scwin.waitingPageInfo && scwin.waitingPageInfo.data) {
            var waitingPageData = scwin.getPageData(scwin.waitingPageInfo.data, scwin.waitingPageInfo);
            dlt_waitingList.setJSON(waitingPageData);
        }

        // 진행중 그리드
        if (scwin.processingPageInfo && scwin.processingPageInfo.data) {
            var processingPageData = scwin.getPageData(scwin.processingPageInfo.data, scwin.processingPageInfo);
            dlt_processingList.setJSON(processingPageData);
        }

        // 완료 그리드
        if (scwin.completedPageInfo && scwin.completedPageInfo.data) {
            var completedPageData = scwin.getPageData(scwin.completedPageInfo.data, scwin.completedPageInfo);
            dlt_completedList.setJSON(completedPageData);
        }
    } catch (err) {
        console.error("그리드 데이터 업데이트 오류:", err);
    }
};

/************************** 페이지 클릭 이벤트 *************************/

// 전체 데이터 페이지 클릭
scwin.pgl_issList_onclick = function (idx) {
    dmp_issVo.set("pageIndex", idx);
    dmp_issVo.set("pageSize", "10");
    $c.sbm.execute($p, sbm_selectIssVoList);
};

// 대기 데이터 페이지 클릭
scwin.pgl_waiting_onclick = function (idx) {
    if (!scwin.waitingPageInfo) return;

    scwin.waitingPageInfo.currentPage = idx;
    var waitingPageData = scwin.getPageData(scwin.waitingPageInfo.data, scwin.waitingPageInfo);
    dlt_waitingList.setJSON(waitingPageData);
    pgl_waiting.setSelectedIndex(idx);
};

// 진행중 데이터 페이지 클릭
scwin.pgl_processing_onclick = function (idx) {
    if (!scwin.processingPageInfo) return;

    scwin.processingPageInfo.currentPage = idx;
    var processingPageData = scwin.getPageData(scwin.processingPageInfo.data, scwin.processingPageInfo);
    dlt_processingList.setJSON(processingPageData);
    pgl_processing.setSelectedIndex(idx);
};

// 완료 데이터 페이지 클릭
scwin.pgl_com_onclick = function (idx) {
    if (!scwin.completedPageInfo) return;

    scwin.completedPageInfo.currentPage = idx;
    var completedPageData = scwin.getPageData(scwin.completedPageInfo.data, scwin.completedPageInfo);
    dlt_completedList.setJSON(completedPageData);
    pgl_com.setSelectedIndex(idx);
};

/************************** 그리드 이벤트 *************************/

// 전체 그리드 셀 클릭 이벤트
scwin.grd_list_oncellclick = function (row, col, colId) {
    dmp_issVoDetail.setJSON(dlt_issVoList.getRowJSON(row));

    btn_save.hide();
    btn_edit.show("");
    btn_delete.show("");
};

// 대기 그리드 더블클릭
scwin.waiting_grd_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    var selectedData = dlt_waitingList.getRowJSON(rowIndex);
    dmp_issVoDetail.setJSON(selectedData);

    pop_overlay.show();

    // 조회 모드로 설정
    scwin.setFormMode("view");

    setTimeout(function() {
        try {
            spn_popupTitle.setValue("대기 이슈/리스크 상세정보");
        } catch(e) {
            setTimeout(function() {
                spn_popupTitle.setValue("대기 이슈/리스크 상세정보");
            }, 50);
        }
    }, 50);

    scwin.loadFileList();
};

// 진행중 그리드 더블클릭
scwin.processing_grd_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    var selectedData = dlt_processingList.getRowJSON(rowIndex);
    dmp_issVoDetail.setJSON(selectedData);

    pop_overlay.show();

    // 조회 모드로 설정
    scwin.setFormMode("view");

    setTimeout(function() {
        try {
            spn_popupTitle.setValue("진행중 이슈/리스크 상세정보");
        } catch(e) {
            setTimeout(function() {
                spn_popupTitle.setValue("진행중 이슈/리스크 상세정보");
            }, 50);
        }
    }, 50);

    scwin.loadFileList();
};

// 완료 그리드 더블클릭
scwin.complete_grd_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    var selectedData = dlt_completedList.getRowJSON(rowIndex);
    dmp_issVoDetail.setJSON(selectedData);

    pop_overlay.show();

    // 조회 모드로 설정
    scwin.setFormMode("view");

    setTimeout(function() {
        try {
            spn_popupTitle.setValue("완료 이슈/리스크 상세정보");
        } catch(e) {
            setTimeout(function() {
                spn_popupTitle.setValue("완료 이슈/리스크 상세정보");
            }, 50);
        }
    }, 50);

    scwin.loadFileList();
};

/************************** 팝업 관련 이벤트 *************************/

// 등록 버튼 클릭 (새 이슈 등록)
scwin.reg_btn_onclick = function (e) {
    dmp_issVoDetail.setEmptyValue();

    // 시연용 데이터 설정
    dmp_issVoDetail.set("pjtId", "6");
    dmp_issVoDetail.set("pjtName", "ERP 시스템 고도화 프로젝트");
    dmp_issVoDetail.set("userId", "1");
    dmp_issVoDetail.set("userName", "김개발");

    dlt_upload.setJSON([]);
    dlt_FileList.setJSON([]);

    pop_overlay.show();

    // 등록 모드로 설정
    scwin.setFormMode("new");

    setTimeout(function() {
        try {
            spn_popupTitle.setValue("이슈리스크 등록");
        } catch(e) {
            setTimeout(function() {
                spn_popupTitle.setValue("이슈리스크 등록");
            }, 50);
        }
    }, 50);

    // 미리보기 초기화
    scwin.hideAllPreviewPanels();
    scwin.showNoPreview();
};

// 팝업 닫기
scwin.detail_esc_btn_onclick = function (e) {
    pop_overlay.hide();
};

// 초기화 버튼
scwin.btn_reset_onclick = function (e) {
    dmp_issVoDetail.setEmptyValue();
    btn_save.show("");
    btn_edit.hide();
    btn_delete.hide();
};

/************************** CRUD 트랜잭션 이벤트 *************************/

// 저장 버튼 클릭 이벤트
scwin.btn_save_onclick = function (e) {
    var issueName = dmp_issVoDetail.get("name");
    if (!issueName || issueName.trim() === "") {
        $c.win.alert("이슈/리스크명을 입력해주세요.");
        return;
    }

    scwin.sendIssueAndFiles();
};

// 수정 버튼 클릭 이벤트
scwin.btn_edit_onclick = function (e) {
    var issueId = dmp_issVoDetail.get("id");
    var issueName = dmp_issVoDetail.get("name");

    if (!issueId || issueId.trim() === "") {
        $c.win.alert("이슈 ID가 없습니다.");
        return;
    }

    if (!issueName || issueName.trim() === "") {
        $c.win.alert("이슈/리스크명을 입력해주세요.");
        return;
    }

    // 수정 모드로 전환
    scwin.setFormMode("edit");

    var promise = $c.win.confirm("수정하시겠습니까?");
    promise.then(function (result) {
        if (result) {
            $c.sbm.execute($p, sbm_updateIssVo);
        } else {
            // 취소 시 조회 모드로 복귀
            scwin.setFormMode("view");
        }
    });
};

// 팝업 수정 버튼 클릭 이벤트 (새로 추가)
scwin.btn_popup_edit_onclick = function(e) {
    // 수정 모드로 전환
    scwin.setFormMode("edit");
};

// 폼 모드 설정 함수 (새로 추가)
scwin.setFormMode = function(mode) {
    console.log("폼 모드 전환:", mode);

    if (mode === "edit") {
        // 수정 모드
        scwin.setFieldsReadOnly(false);
        scwin.setEditorMode(true);
        scwin.showFileUploadSection(true);

        // 버튼 상태 변경
        btn_save.show();
        btn_popup_edit.hide();

    } else if (mode === "view") {
        // 조회 모드
        scwin.setFieldsReadOnly(true);
        scwin.setEditorMode(false);
        scwin.showFileUploadSection(false);

        // 버튼 상태 변경
        btn_save.hide();
        btn_popup_edit.show();
    } else if (mode === "new") {
        // 등록 모드
        scwin.setFieldsReadOnly(false);
        scwin.setEditorMode(true);
        scwin.showFileUploadSection(true);

        // 버튼 상태 변경
        btn_save.show();
        btn_popup_edit.hide();
        btn_popup_delete.hide();
    }
};

// 필드 읽기 전용 설정 함수 (새로 추가)
scwin.setFieldsReadOnly = function(readOnly) {
    try {
        // 편집 가능한 필드들
        var editableFields = [
            "inp_issueName",     // 이슈/리스크명
            "sel_priority",      // 우선순위
            "sel_status",        // 상태
            "cal_dueDate",       // 완료예정일
            "cal_resolvedDate"   // 해결일
        ];

        editableFields.forEach(function(fieldId) {
            var field = $p.getComponentById(fieldId);
            if (field && field.setReadOnly) {
                field.setReadOnly(readOnly);
            }
        });

        // 프로젝트명과 담당자명은 항상 readOnly
        var alwaysReadOnlyFields = ["inp_projectName", "inp_userName"];
        alwaysReadOnlyFields.forEach(function(fieldId) {
            var field = $p.getComponentById(fieldId);
            if (field && field.setReadOnly) {
                field.setReadOnly(true);
            }
        });

    } catch(e) {
        console.error("필드 읽기 전용 설정 오류:", e);
    }
};


// 이슈와 파일 전송
scwin.sendIssueAndFiles = function () {
    console.log("sendIssueAndFiles() 시작됨");

    var formData = new FormData();

    formData.append("pjtId", dmp_issVoDetail.get("pjtId"));
    formData.append("name", dmp_issVoDetail.get("name"));
    formData.append("userId", dmp_issVoDetail.get("userId"));
    formData.append("dueDate", dmp_issVoDetail.get("dueDate"));
    formData.append("status", dmp_issVoDetail.get("status") || "PEN");
    formData.append("priority", dmp_issVoDetail.get("priority") || "MD");
    formData.append("description", dmp_issVoDetail.get("description"));
    formData.append("responsePlan", dmp_issVoDetail.get("responsePlan"));
    formData.append("resolvedDate", dmp_issVoDetail.get("resolvedDate"));

    // 파일 추가
    if (mpd_html5Type && mpd_html5Type.fileArray) {
        var fileList = mpd_html5Type.fileArray;
        console.log("fileList", fileList);

        if (fileList && fileList.length > 0) {
            for (var i = 0; i < fileList.length; i++) {
                var realFile = fileList[i].file;
                console.log('real', realFile);
                formData.append("files", realFile);
            }
        }
    }

    fetch("/InsWebApp/ISS001InsWithFiles.pwkjson", {
        method: "POST",
        body: formData
    })
    .then(function(res) { return res.json(); })
    .then(function(res) {
        $c.win.alert("등록되었습니다.");
        dlt_upload.removeAll();
        if (mpd_html5Type && mpd_html5Type.removeAllFiles) {
            mpd_html5Type.removeAllFiles();
        }
        pop_overlay.hide();
        scwin.btn_search_onclick();
    })
    .catch(function(err) {
        console.error("전송 실패", err);
        $c.win.alert("트랜잭션 실패");
    });
};

// 일반 수정 완료 콜백
// 수정 완료 후 조회 모드로 전환
scwin.sbm_updateIssVo_submitdone = function (e) {
    var elHeader = e.responseJSON.elHeader;
    if (!elHeader || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    $c.win.alert("수정되었습니다.");

    // 조회 모드로 전환
    scwin.setFormMode("view");

    // 데이터 새로고침
    scwin.btn_search_onclick();
};

// 삭제 버튼 클릭 이벤트
scwin.btn_delete_onclick = function (e) {
    var issueId = dmp_issVoDetail.get("id");

    if (!issueId) {
        $c.win.alert("삭제할 이슈를 선택해주세요.");
        return;
    }

    var promise = $c.win.confirm("삭제하시겠습니까?\n관련된 파일도 함께 삭제됩니다.");
    promise.then(function (result) {
        if (result) {
            $c.sbm.execute($p, sbm_deleteIssVo);
        }
    });
};

// 삭제 완료 콜백
scwin.sbm_deleteIssVo_submitdone = function (e) {
    var elHeader = e.responseJSON.elHeader;
    if (!elHeader || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    $c.win.alert("삭제되었습니다.");
    pop_overlay.hide();
    scwin.btn_search_onclick();
};

/************************** 파일 관련 함수 (새로 추가) *************************/

// 탭 변경 이벤트
scwin.tab_main_onchange = function(e) {
    var selectedTab = e.newSelectedIndex;

    // 첨부파일 탭 선택 시 파일 목록 로드
    if (selectedTab === 1) {
        setTimeout(function() {
            scwin.loadFileList();
        }, 100);
    }
};

// 파일 선택 완료 콜백
scwin.multiUploadSelectDone = function () {
    console.log("파일 선택 완료 콜백 실행");
    var fileInfos = mpd_html5Type.getFileInfos();
    var newFileData = [];

    for (var i = 0; i < fileInfos.length; i++) {
        var file = fileInfos[i];
        newFileData.push({
            originalFileName: file.name,
            fileSize: file.size,
            fileExtension: scwin.getFileExtension(file.name),
            status: "업로드 대기",        // 상태 필드 추가
            action: "❌"                // 작업 필드 추가
        });
    }

    dlt_upload.setJSON(newFileData);
    try {
        grd_uploadList.refresh();
    } catch(e) {
        console.log("그리드 새로고침 실패, 무시");
    }

    console.log("업로드 대기 파일 수:", newFileData.length);
};

// 파일 확장자 추출
scwin.getFileExtension = function(fileName) {
    if (!fileName || fileName.indexOf('.') === -1) return '';
    return fileName.split('.').pop().toLowerCase();
};

// 파일 목록 로드
scwin.loadFileList = function() {

    console.log("=== 파일 목록 로드 시작 ===");

    // 현재 선택된 이슈 ID 확인
    var issueId = dmp_issVoDetail.get("id");
    console.log("이슈 ID:", issueId);

